#define DRAW_DEPTH       0.5f
#define DRAW_TEXT_GLYPH  8192 /* glyphs per frame; the top screen is drawn once per eye */
#define DRAW_CLIP_DEPTH  8
#define DRAW_STATE_DEPTH 8
#define DRAW_TEXT_MAX    256 /* longest text that draw_text_fit shortens */

typedef struct {
    int index;
    GeomInsets insets; /* fixed borders of the image */
    GeomInsets outset; /* how far the image reaches beyond the box */
} SliceInfo;

