static C2D_SpriteSheet s_sheet;
static C2D_TextBuf s_text_buf;
static C2D_TextBuf s_measure_buf;

static int s_screen_w = THEME_TOP_W;
static GeomRect s_clip[DRAW_CLIP_DEPTH];
static int s_clip_top;

/* Offset and opacity applied to every call, see draw_translate_push(). */
static int s_dx[DRAW_STATE_DEPTH], s_dy[DRAW_STATE_DEPTH];
static int s_move_top;
static u8 s_opacity[DRAW_STATE_DEPTH];
static int s_opacity_top;

/* --- Setup --------------------------------------------------------------- */

Result draw_init(void)
{
    s_sheet = C2D_SpriteSheetLoad("romfs:/gfx/ui.t3x");
    if (!s_sheet)
        return MAKERESULT(RL_FATAL, RS_NOTFOUND, RM_APPLICATION, RD_NOT_FOUND);

    /* 1:1 draws at whole pixels sample texel centers, so linear filtering only
     * smooths scaled sprites and stretched slices. */
    C3D_TexSetFilter(C2D_SpriteSheetGetImage(s_sheet, 0).tex, GPU_LINEAR, GPU_LINEAR);

    s_text_buf = C2D_TextBufNew(DRAW_TEXT_GLYPH);
    s_measure_buf = C2D_TextBufNew(DRAW_TEXT_MAX);
    if (!s_text_buf || !s_measure_buf) {
        draw_fini();
        return MAKERESULT(RL_FATAL, RS_OUTOFRESOURCE, RM_APPLICATION, RD_OUT_OF_MEMORY);
    }
    return 0;
}

void draw_fini(void)
{
    if (s_measure_buf)
        C2D_TextBufDelete(s_measure_buf);
    if (s_text_buf)
        C2D_TextBufDelete(s_text_buf);
    if (s_sheet)
        C2D_SpriteSheetFree(s_sheet);
    s_measure_buf = NULL;
    s_text_buf = NULL;
    s_sheet = NULL;
}

void draw_frame_begin(void)
{
    C2D_TextBufClear(s_text_buf);
    art_source_frame();
}

static void apply_clip(void)
{
    C2D_Flush();
    GeomRect c = s_clip[s_clip_top];
    if (c.x <= 0 && c.y <= 0 && c.x + c.w >= s_screen_w && c.y + c.h >= THEME_SCREEN_H) {
        C3D_SetScissor(GPU_SCISSOR_DISABLE, 0, 0, 0, 0);
        return;
    }
    GeomScissor s = geom_scissor(c, s_screen_w, THEME_SCREEN_H);
    C3D_SetScissor(GPU_SCISSOR_NORMAL, s.left, s.top, s.right, s.bottom);
}

void draw_screen_begin(C3D_RenderTarget *target, int screen_w)
{
    C2D_SceneBegin(target);
    s_screen_w = screen_w;
    s_clip_top = 0;
    s_clip[0] = (GeomRect){0, 0, screen_w, THEME_SCREEN_H};
    s_move_top = 0;
    s_dx[0] = s_dy[0] = 0;
    s_opacity_top = 0;
    s_opacity[0] = THEME_ALPHA_OPAQUE;
    apply_clip();
}

void draw_translate_push(int dx, int dy)
{
    if (s_move_top + 1 >= DRAW_STATE_DEPTH)
        svcBreak(USERBREAK_ASSERT);
    s_dx[s_move_top + 1] = s_dx[s_move_top] + dx;
    s_dy[s_move_top + 1] = s_dy[s_move_top] + dy;
    s_move_top++;
}

void draw_translate_pop(void)
{
    if (s_move_top == 0)
        svcBreak(USERBREAK_ASSERT);
    s_move_top--;
}

void draw_opacity_push(u8 opacity)
{
    if (s_opacity_top + 1 >= DRAW_STATE_DEPTH)
        svcBreak(USERBREAK_ASSERT);
    s_opacity[s_opacity_top + 1] = (u8)(s_opacity[s_opacity_top] * opacity / 255);
    s_opacity_top++;
}

void draw_opacity_pop(void)
{
    if (s_opacity_top == 0)
        svcBreak(USERBREAK_ASSERT);
    s_opacity_top--;
}

static int move_x(int x)
{
    return x + s_dx[s_move_top];
}

static int move_y(int y)
{
    return y + s_dy[s_move_top];
}

static u8 fade(u8 alpha)
{
    return (u8)(alpha * s_opacity[s_opacity_top] / 255);
}

/* Nothing can be visible inside an empty clip; skip the draw. */
static bool clipped_away(void)
{
    return geom_rect_empty(s_clip[s_clip_top]);
}

void draw_clip_push(GeomRect r)
{
    if (s_clip_top + 1 >= DRAW_CLIP_DEPTH)
        svcBreak(USERBREAK_ASSERT); /* nesting this deep is a programming error */
    GeomRect next;
    r.x = move_x(r.x);
    r.y = move_y(r.y);
    geom_rect_intersect(s_clip[s_clip_top], r, &next);
    s_clip[++s_clip_top] = next;
    apply_clip();
}

void draw_clip_pop(void)
{
    if (s_clip_top == 0)
        svcBreak(USERBREAK_ASSERT);
    s_clip_top--;
    apply_clip();
}

/* --- Flat areas ---------------------------------------------------------- */

void draw_rect(int x, int y, int w, int h, ThemeColor color, u8 alpha)
{
    if (clipped_away())
        return;
    C2D_DrawRectSolid(move_x(x), move_y(y), DRAW_DEPTH, w, h, theme_color(color, fade(alpha)));
}

void draw_gradient_v(int x, int y, int w, int h, ThemeColor top, ThemeColor bottom, u8 alpha)
{
    if (clipped_away())
        return;
    u32 t = theme_color(top, fade(alpha)), b = theme_color(bottom, fade(alpha));
    C2D_DrawRectangle(move_x(x), move_y(y), DRAW_DEPTH, w, h, t, t, b, b);
}

void draw_gradient_h(int x, int y, int w, int h, ThemeColor left, ThemeColor right, u8 alpha)
{
    if (clipped_away())
        return;
    u32 l = theme_color(left, fade(alpha)), r = theme_color(right, fade(alpha));
    C2D_DrawRectangle(move_x(x), move_y(y), DRAW_DEPTH, w, h, l, r, l, r);
}

void draw_ellipse(int x, int y, int w, int h, ThemeColor color, u8 alpha)
{
    if (clipped_away())
        return;
    C2D_DrawEllipseSolid(move_x(x), move_y(y), DRAW_DEPTH, w, h, theme_color(color, fade(alpha)));
}

/* --- Atlas images -------------------------------------------------------- */

static C2D_Image atlas_image(int index)
{
    return C2D_SpriteSheetGetImage(s_sheet, index);
}

int draw_sprite_width(DrawSprite sprite)
{
    return atlas_image(s_sprite_index[sprite]).subtex->width;
}

int draw_sprite_height(DrawSprite sprite)
{
    return atlas_image(s_sprite_index[sprite]).subtex->height;
}

static void alpha_tint(C2D_ImageTint *tint, u8 alpha)
{
    C2D_AlphaImageTint(tint, fade(alpha) / 255.0f);
}

void draw_sprite(DrawSprite sprite, int x, int y, u8 alpha)
{
    if (clipped_away())
        return;
    C2D_ImageTint tint;
    alpha_tint(&tint, alpha);
    C2D_DrawImageAt(atlas_image(s_sprite_index[sprite]), move_x(x), move_y(y), DRAW_DEPTH, &tint,
                    1.0f, 1.0f);
}

void draw_image(const C2D_Image *image, GeomRect dst, u8 alpha)
{
    if (clipped_away() || dst.w <= 0 || dst.h <= 0)
        return;
    C2D_ImageTint tint;
    alpha_tint(&tint, alpha);
    C2D_DrawParams p = {
        .pos = {(float)move_x(dst.x), (float)move_y(dst.y), (float)dst.w, (float)dst.h},
        .center = {0.0f, 0.0f},
        .depth = DRAW_DEPTH,
        .angle = 0.0f,
    };
    C2D_DrawImage(*image, &p, &tint);
}

void draw_sprite_scaled(DrawSprite sprite, int cx, int cy, float scale, u8 alpha)
{
    if (clipped_away())
        return;
    C2D_Image img = atlas_image(s_sprite_index[sprite]);
    float w = img.subtex->width * scale, h = img.subtex->height * scale;
    C2D_ImageTint tint;
    alpha_tint(&tint, alpha);
    C2D_DrawParams p = {
        .pos = {move_x(cx) - w / 2.0f, move_y(cy) - h / 2.0f, w, h},
        .center = {0.0f, 0.0f},
        .depth = DRAW_DEPTH,
        .angle = 0.0f,
    };
    C2D_DrawImage(img, &p, &tint);
}

void draw_sprite_tiled(DrawSprite sprite, GeomRect area, int off_x, int off_y)
{
    int w = draw_sprite_width(sprite), h = draw_sprite_height(sprite);
    if (w <= 0 || h <= 0)
        return;
    /* Start one tile before the area so any offset is covered. */
    int sx = area.x + ((off_x % w) + w) % w - w;
    int sy = area.y + ((off_y % h) + h) % h - h;

    draw_clip_push(area);
    if (!clipped_away()) {
        for (int y = sy; y < area.y + area.h; y += h)
            for (int x = sx; x < area.x + area.w; x += w)
                draw_sprite(sprite, x, y, THEME_ALPHA_OPAQUE);
    }
    draw_clip_pop();
}

void draw_awning(int screen_w)
{
    GeomRect area = {0, 0, screen_w, draw_sprite_height(DRAW_AWNING)};
    draw_sprite_tiled(DRAW_AWNING, area, 0, 0);
}

/* Linear mix of two citro2d colors, t in 0..1. */
static u32 mix_color(u32 a, u32 b, float t)
{
    u32 out = 0;
    for (int shift = 0; shift < 32; shift += 8) {
        float ca = (a >> shift) & 0xFF, cb = (b >> shift) & 0xFF;
        out |= (u32)lroundf(ca + (cb - ca) * t) << shift;
    }
    return out;
}

static void draw_slice_impl(DrawSlice slice, GeomRect box, const u32 *grad, u8 alpha)
{
    if (clipped_away())
        return;
    const SliceInfo *info = &s_slices[slice];
    C2D_Image img = atlas_image(info->index);
    const Tex3DS_SubTexture *st = img.subtex;

    box.x = move_x(box.x);
    box.y = move_y(box.y);
    GeomRect dst = {box.x - info->outset.left, box.y - info->outset.top,
                    box.w + info->outset.left + info->outset.right,
                    box.h + info->outset.top + info->outset.bottom};
    GeomPatch patches[GEOM_NINE_SLICE_MAX];
    int n = geom_nine_slice(st->width, st->height, info->insets, dst, patches);

    /* tex3ds may store an image rotated in the atlas (then top < bottom and
     * citro2d swaps u and v). Interpolating each field along the image's own
     * x (left/right) and y (top/bottom) is correct for both layouts. */
    float du = (st->right - st->left) / st->width;
    float dv = (st->bottom - st->top) / st->height;

    for (int i = 0; i < n; i++) {
        const GeomPatch *p = &patches[i];
        Tex3DS_SubTexture sub = {
            .width = (u16)p->src.w,
            .height = (u16)p->src.h,
            .left = st->left + du * p->src.x,
            .top = st->top + dv * p->src.y,
            .right = st->left + du * (p->src.x + p->src.w),
            .bottom = st->top + dv * (p->src.y + p->src.h),
        };
        C2D_Image part = {img.tex, &sub};
        C2D_ImageTint tint;
        if (grad) {
            /* Gradient over the whole box, sampled at this patch's top and bottom. */
            float t0 = (float)(p->dst.y - dst.y) / dst.h;
            float t1 = (float)(p->dst.y + p->dst.h - dst.y) / dst.h;
            u32 c0 = mix_color(grad[0], grad[1], t0), c1 = mix_color(grad[0], grad[1], t1);
            C2D_SetImageTint(&tint, C2D_TopLeft, c0, 1.0f);
            C2D_SetImageTint(&tint, C2D_TopRight, c0, 1.0f);
            C2D_SetImageTint(&tint, C2D_BotLeft, c1, 1.0f);
            C2D_SetImageTint(&tint, C2D_BotRight, c1, 1.0f);
        } else {
            alpha_tint(&tint, alpha);
        }
        C2D_DrawParams params = {
            .pos = {p->dst.x, p->dst.y, p->dst.w, p->dst.h},
            .center = {0.0f, 0.0f},
            .depth = DRAW_DEPTH,
            .angle = 0.0f,
        };
        C2D_DrawImage(part, &params, &tint);
    }
}

void draw_slice(DrawSlice slice, GeomRect box, u8 alpha)
{
    draw_slice_impl(slice, box, NULL, alpha);
}

void draw_slice_tinted(DrawSlice slice, GeomRect box, ThemeColor top, ThemeColor bottom, u8 alpha)
{
    u32 grad[2] = {theme_color(top, fade(alpha)), theme_color(bottom, fade(alpha))};
    draw_slice_impl(slice, box, grad, alpha);
}

/* --- Text ---------------------------------------------------------------- */

static float text_width_f(float scale, const char *text)
{
    C2D_Text t;
    C2D_TextBufClear(s_measure_buf);
    if (!C2D_TextParse(&t, s_measure_buf, text))
        return 0.0f;
    float w = 0.0f, h = 0.0f;
    C2D_TextGetDimensions(&t, scale, scale, &w, &h);
    return w;
}

int draw_text_width(int px, const char *text)
{
    return (int)ceilf(text_width_f(theme_text_scale(px), text));
}

int draw_text_height(int px)
{
    return theme_text_line_height(px);
}

static int draw_text_n(int x, int y, int px, ThemeColor color, u8 alpha, DrawAlign align,
                       const char *text)
{
    float scale = theme_text_scale(px);
    C2D_Text t;
    if (!C2D_TextParse(&t, s_text_buf, text))
        return 0;
    C2D_TextOptimize(&t);
    float w = 0.0f, h = 0.0f;
    C2D_TextGetDimensions(&t, scale, scale, &w, &h);

    int left = x;
    if (align == DRAW_ALIGN_CENTER)
        left = x - (int)lroundf(w / 2.0f);
    else if (align == DRAW_ALIGN_RIGHT)
        left = x - (int)lroundf(w);

    if (!clipped_away())
        C2D_DrawText(&t, C2D_WithColor, move_x(left), move_y(y), DRAW_DEPTH, scale, scale,
                     theme_color(color, fade(alpha)));
    return (int)ceilf(w);
}

int draw_text(int x, int y, int px, ThemeColor color, u8 alpha, DrawAlign align, const char *text)
{
    return draw_text_n(x, y, px, color, alpha, align, text);
}

typedef struct {
    float scale;
    char buf[DRAW_TEXT_MAX + 1];
} MeasureCtx;

static int measure_prefix(const char *s, size_t len, void *ctx)
{
    MeasureCtx *m = ctx;
    if (len > DRAW_TEXT_MAX)
        len = DRAW_TEXT_MAX;
    memcpy(m->buf, s, len);
    m->buf[len] = '\0';
    return (int)ceilf(text_width_f(m->scale, m->buf));
}

int draw_text_fit(int x, int y, int max_w, int px, ThemeColor color, u8 alpha, DrawAlign align,
                  const char *text)
{
    MeasureCtx m = {.scale = theme_text_scale(px)};
    int ellipsis_w = (int)ceilf(text_width_f(m.scale, TEXT_FIT_ELLIPSIS));
    bool cut = false;
    size_t n = text_fit(text, max_w, ellipsis_w, measure_prefix, &m, &cut);
    if (!cut)
        return draw_text_n(x, y, px, color, alpha, align, text);

    char out[DRAW_TEXT_MAX + sizeof(TEXT_FIT_ELLIPSIS)];
    if (n > DRAW_TEXT_MAX)
        n = DRAW_TEXT_MAX;
    memcpy(out, text, n);
    memcpy(out + n, TEXT_FIT_ELLIPSIS, sizeof(TEXT_FIT_ELLIPSIS));
    return draw_text_n(x, y, px, color, alpha, align, out);
}

int draw_text_wrapped(int x, int y, int max_w, int line_h, int max_lines, int px, ThemeColor color,
                      u8 alpha, DrawAlign align, const char *text)
{
    if (max_lines > DRAW_WRAP_MAX_LINES)
        max_lines = DRAW_WRAP_MAX_LINES;
    MeasureCtx m = {.scale = theme_text_scale(px)};
    TextLine lines[DRAW_WRAP_MAX_LINES];
    bool cut = false;
    int n = text_wrap(text, max_w, measure_prefix, &m, lines, max_lines, &cut);

    char buf[DRAW_TEXT_MAX + 1];
    for (int i = 0; i < n; i++) {
        size_t len = lines[i].len > DRAW_TEXT_MAX ? DRAW_TEXT_MAX : lines[i].len;
        memcpy(buf, text + lines[i].start, len);
        buf[len] = '\0';
        int ly = y + i * line_h;
        if (cut && i == n - 1)
            draw_text_fit(x, ly, max_w, px, color, alpha, align, buf);
        else
            draw_text_n(x, ly, px, color, alpha, align, buf);
    }
    return n;
}

int draw_text_vcenter(int x, int y, int h, int px, ThemeColor color, u8 alpha, DrawAlign align,
                      const char *text)
{
    int top = y + (h - draw_text_height(px)) / 2;
    return draw_text_n(x, top, px, color, alpha, align, text);
}
